CREATE TABLE "blog_posts" (post_id INTEGER PRIMARY KEY AUTOINCREMENT UNIQUE NOT NULL, blog_id TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, summary TEXT NOT NULL, edited_at DATETIME DEFAULT NULL NOT NULL, created_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP));
CREATE TABLE "blog_comments" (blog_id TEXT NOT NULL, post_id INTEGER REFERENCES blog_posts (post_id) NOT NULL, comment_id INTEGER NOT NULL, parent_comment_id INTEGER NOT NULL, author_id TEXT NOT NULL, content TEXT NOT NULL, edited_at DATETIME NOT NULL, created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL);
CREATE TABLE "protocall_room_access" (room_id TEXT REFERENCES protocall_rooms (id) NOT NULL, user_id TEXT NOT NULL, access INTEGER NOT NULL);
CREATE TABLE "protocall_messages" (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL UNIQUE, local_id INTEGER NOT NULL, room_id TEXT REFERENCES protocall_rooms (id) NOT NULL, content TEXT NOT NULL, author_id TEXT REFERENCES users (id) NOT NULL, created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL);
CREATE TABLE "forum_topics" (id TEXT PRIMARY KEY NOT NULL UNIQUE, forum_id TEXT REFERENCES forum_forums (id) NOT NULL, name TEXT NOT NULL COLLATE NOCASE, description TEXT NOT NULL, total_posts INTEGER NOT NULL DEFAULT (0), locked BOOLEAN NOT NULL DEFAULT (0), creator_id TEXT REFERENCES users (id) NOT NULL, updated_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP), created_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP), UNIQUE (forum_id, name)) WITHOUT ROWID;
CREATE TABLE "forum_forums" (id TEXT PRIMARY KEY UNIQUE NOT NULL, name TEXT UNIQUE NOT NULL COLLATE NOCASE, description TEXT NOT NULL, creator_id TEXT REFERENCES users (id) NOT NULL, created_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP)) WITHOUT ROWID;
CREATE TABLE "forum_posts" (id INTEGER PRIMARY KEY AUTOINCREMENT NOT NULL UNIQUE, topic_id TEXT REFERENCES forum_topics (id) NOT NULL, content TEXT NOT NULL, show_signature BOOLEAN NOT NULL, deleted BOOLEAN NOT NULL DEFAULT (0), creator_id TEXT REFERENCES users (id) NOT NULL, created_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP));
CREATE TRIGGER decrementTotalPosts AFTER DELETE ON forum_posts BEGIN UPDATE forum_topics SET total_posts = total_posts - 1, updated_at = CURRENT_TIMESTAMP WHERE id = OLD.topic_id; END;
CREATE TRIGGER incrementTotalPosts AFTER INSERT ON forum_posts BEGIN UPDATE forum_topics SET total_posts = total_posts + 1, updated_at = CURRENT_TIMESTAMP WHERE id = NEW.topic_id; END;
CREATE TABLE "users" (id TEXT PRIMARY KEY NOT NULL, username TEXT UNIQUE NOT NULL COLLATE NOCASE, password_hash TEXT NOT NULL, profile_picture_url TEXT NOT NULL, description TEXT NOT NULL, signature TEXT NOT NULL, email TEXT NOT NULL, email_public BOOLEAN NOT NULL DEFAULT (0), color TEXT NOT NULL, created_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP)) WITHOUT ROWID;
CREATE TABLE "protocall_rooms" (id TEXT PRIMARY KEY NOT NULL UNIQUE, author_id TEXT NOT NULL, name TEXT NOT NULL COLLATE NOCASE UNIQUE, description TEXT NOT NULL, is_public BOOLEAN NOT NULL, total_messages INTEGER NOT NULL, updated_at DATETIME NOT NULL DEFAULT (CURRENT_TIMESTAMP), created_at DATETIME DEFAULT (CURRENT_TIMESTAMP) NOT NULL) WITHOUT ROWID;